assert sys.flags.isolated and sys.flags.no_site
root=Path(__file__).resolve().parents[2];repo=root.parents[1];p=root/'research/nine-sharing-sign17-lines-rails-check';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest()
