e,=json.loads((p/'source-manifest.json').read_text())['rows'];n='Sign17LinesRails';q=p/'src/DiophantineConsistency'/(n+'.lean');s=q.read_text();assert e['module']=='DiophantineConsistency.'+n and e['imports']==['DiophantineConsistency.Sign17LinesDecoder'] and sha(q)==sha(repo/e['source'])==e['source_sha256']=='84ce926ce2cd0c66fc90346556a2d2856dd8f908f9893c40e06d7cce5366e483' and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==e['imports'] and not re.search(r'(?m)^\s*(axiom|opaque|partial)\b|\b(sorry|admit|native_decide)\b',s)
for z in ('List.ofFn (fun j : Fin 430 => Sign17ParamDecoder.actionAt displayedSeed j.val)','WangTiles942.cachedActions = lineActions','WangTiles942.targets d =','WangTiles942.targetsFrom d lineActions','WangTiles942.rail d q =','205 - 199 * d.toNat +','(WangTiles942.targetsFrom d lineActions ∩ Finset.range q).card','WangTiles942.transitionRow j =','transition_row_from_lines, rail_from_lines'):assert z in s
old=(root/'Lean/DiophantineConsistency/WangTiles942Data.lean').read_text();assert 'def cachedActions : List Action := List.ofFn action' in old and 'targets d = targetsFrom d cachedActions' in old and '205 - 199 * d.toNat + (targets d ∩ Finset.range q).card' in old and 'theorem rail_eq_formula (d : Bool) (q : ℕ)' in old
subprocess.run([sys.executable,'-I','-S','-B',str(root/'reviews/nine-sharing-sign17-lines-decoder-terminal-independent/check.py')],capture_output=True,check=True,timeout=180)
prior=json.loads((root/'research/nine-sharing-sign17-lines-decoder-check/attempt01/state.json').read_text());assert prior['status']=='PASS';obj=Path('/tmp/nine-sharing-sign17-lines-decoder-20261110/lib/DiophantineConsistency/Sign17LinesDecoder.olean');assert sha(obj)==prior['rows'][0]['object_sha256']
r=(p/'run.py').read_text();assert "need('Init' in deps" in r and "env['LEAN_NUM_THREADS']='1'" in r and "str(candidates[0])==rec['path']" in r and "rec['realpath']==provider_init['realpath'] and rec['sha256']==provider_init['sha256']" in r and "'-M3600'" in r and "'-j1'" in r and 'rss_limit=4*1024**3,mem_floor=10*1024**3,seconds=120,interval=.1' in r
x=subprocess.run([sys.executable,'-I','-S','-B',str(p/'run.py'),'--preflight'],capture_output=True,text=True,check=True,timeout=180);assert not x.stderr and json.loads(x.stdout)['status']=='PASS_NO_LEAN_PREFLIGHT'
print(json.dumps({'status':'PASS_PRELAUNCH','scope':'in-Lean decimal lines to action list, target sets, rail values and 430 transition rows; full table/PDF/file separate'},indent=2))
